            return false
        }
        if lhs.nodeId != rhs.nodeId {
            return false
        }
        if lhs.ipv6 != rhs.ipv6 {
            return false
        }
        if lhs.peers != rhs.peers {
            return false
        }
        if lhs.networks != rhs.networks {
            return false
        }
        if lhs.pendingNetworks != rhs.pendingNetworks {
            return false
        }
        if lhs.identity != rhs.identity {
            return false
